 internal static Routine Find(uint original){foreach(var r in Routines)if(r.Original==original)return r;throw new Exception("Missing actor-storage routine");}
 internal static byte[] Build(Routine r,uint placed,Func<uint,uint> bind){
  var bytes=(byte[])r.Template.Clone();
  foreach(var f in r.Fixups){uint target=bind==null?f.Target:bind(f.Target);uint value=f.Relative?unchecked(target-(placed+(uint)f.Offset+4)):target;Array.Copy(BitConverter.GetBytes(value),0,bytes,f.Offset,4);}
  return bytes;
 }
 internal static List<NativeWormCaches64.Patch> GetPatches(uint code,uint pair){
  var patches=new List<NativeWormCaches64.Patch>();
  patches.Add(new NativeWormCaches64.Patch(0x536f39,BitConverter.GetBytes(0x1e0),BitConverter.GetBytes(ObjectSize)));
  patches.Add(new NativeWormCaches64.Patch(0x4dfa59,BitConverter.GetBytes(0x178),BitConverter.GetBytes(0x3b8)));
  patches.Add(new NativeWormCaches64.Patch(0x507be9,BitConverter.GetBytes(0xa8),BitConverter.GetBytes(0xe8)));
  foreach(var r in Routines){
   uint at=code+(uint)r.Offset;byte[] bytes=Build(r,at,target=>target==0x82f0f0?pair:target);
   patches.Add(new NativeWormCaches64.Patch(at,new byte[bytes.Length],bytes));
   var expected=new byte[r.HookSize];Array.Copy(r.Expected,expected,expected.Length);
   var hook=new byte[r.HookSize];for(int i=0;i<hook.Length;i++)hook[i]=0x90;hook[0]=0xe9;
   Array.Copy(BitConverter.GetBytes(unchecked(at-r.Original-5)),0,hook,1,4);
   patches.Add(new NativeWormCaches64.Patch(r.Original,expected,hook));
  }
  return patches;
 }
 internal static void CheckDisk(byte[] disk){
  foreach(var r in Routines)for(int i=0;i<r.Expected.Length;i++)if(disk[checked((int)(r.Original-0x400000))+i]!=r.Expected[i])throw new Exception("Actor-storage original bytes mismatch at "+r.Original.ToString("X8"));
  if(BitConverter.ToInt32(disk,0x136f39)!=0x1e0)throw new Exception("Unexpected manager allocation size");
 }
